import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.gtmkOXzY.js";const u=JSON.parse('{"title":"Airports, locations and airspace","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/airports.md","filePath":"ms-flightsim/airports.md","lastUpdated":null}'),i={name:"ms-flightsim/airports.md"};function d(n,t,s,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="airports-locations-and-airspace" tabindex="-1">Airports, locations and airspace <a class="header-anchor" href="#airports-locations-and-airspace" aria-label="Permalink to &quot;Airports, locations and airspace&quot;">​</a></h1><p>Six airports ship ready to fly, admins add or adjust more in game with <code>/adminps</code>, and the airspace rules keep pilots off the city and on the runways.</p><h2 id="built-in-airports" tabindex="-1">Built-in airports <a class="header-anchor" href="#built-in-airports" aria-label="Permalink to &quot;Built-in airports&quot;">​</a></h2><p>These come from <code>Config.Airports</code> in <code>config.lua</code>. Each airport is a circle: a centre and a radius.</p><table tabindex="0"><thead><tr><th>Airport</th><th>Radius</th><th>Runways</th><th>Job location</th></tr></thead><tbody><tr><td>LSIA</td><td>1,500 m</td><td>12R/30L, 12L/30R, 03/21 (short)</td><td>On</td></tr><tr><td>Sandy Shores</td><td>600 m</td><td>12/30, 09/27</td><td>On</td></tr><tr><td>Grapeseed</td><td>500 m</td><td>06/24</td><td>On</td></tr><tr><td>Cayo Perico</td><td>450 m</td><td>13/31</td><td>Off</td></tr><tr><td>Roxwood</td><td>550 m</td><td>17/35</td><td>Off</td></tr><tr><td>Vespucci Helipad</td><td>130 m</td><td>none (helicopters)</td><td>none</td></tr></tbody></table><ul><li>Roxwood is a custom map. It only works if you run the Roxwood County map resource.</li><li>Cayo Perico and Roxwood ship switched off. Turn them on in the <strong>Locations</strong> tab (see below).</li><li>Inside any airport radius, altitude zones never apply. Pilots can descend, land and take off freely.</li></ul><h2 id="add-a-custom-airport" tabindex="-1">Add a custom airport <a class="header-anchor" href="#add-a-custom-airport" aria-label="Permalink to &quot;Add a custom airport&quot;">​</a></h2><p>Custom airports are stored in the database. They survive restarts and script updates. Changes to an airport apply after you restart MS_FlightSim.</p><ol><li>Walk to where you want the airport centre.</li><li>Open <code>/adminps</code> and go to the <strong>Airports</strong> tab.</li><li>Type a <strong>Label</strong> (up to 60 characters). It must not match an existing airport.</li><li>Click <strong>Use My Position</strong> to fill in the centre.</li><li>Set the <strong>Radius</strong>: 50 to 5,000 m, default 800 m. It should cover the runways, the apron and the approach.</li><li>Click <strong>Add Airport</strong>.</li><li>Click <strong>Manage</strong> on the new airport card and fill in the sections below.</li><li>Restart MS_FlightSim.</li></ol><h3 id="what-you-can-set-on-a-custom-airport" tabindex="-1">What you can set on a custom airport <a class="header-anchor" href="#what-you-can-set-on-a-custom-airport" aria-label="Permalink to &quot;What you can set on a custom airport&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>What it does</th></tr></thead><tbody><tr><td>Replaces</td><td>Hides a built-in job location this airport sits on top of, so you don&#39;t get duplicate NPCs and blips. Applies at once.</td></tr><tr><td>Runways</td><td>Stand at one end and click <strong>Capture A</strong>, then at the other end and click <strong>Capture B</strong>. Type the runway numbers (B is optional for a one-way runway) and click <strong>Add Runway</strong>.</td></tr><tr><td>Heli Spawn</td><td>Where the medevac rescue helicopter appears for this airport. Without it, the nearest helipad is used.</td></tr><tr><td>Helipads</td><td>Extra pads, used by medevac, firefighting, heavy lift, supply drop, VIP extraction and helicopter landings.</td></tr><tr><td>Cargo NPC</td><td>The dispatcher players talk to, to start missions here.</td></tr><tr><td>Cargo job</td><td>Plane spawn, forklift and three pallets. With all five captured, the airport appears as a cargo and smuggling destination.</td></tr><tr><td>Passenger / tourist spawn</td><td>Where boarding passengers wait for passenger, sightseeing and survey jobs. Falls back to the plane spawn.</td></tr><tr><td>Plane spawn points</td><td>Extra parking slots. Jobs use the first free one. They only work once the cargo job above is complete.</td></tr><tr><td>Services</td><td>Dealer, trainer, painter and mechanic NPCs. Set only the ones this airport offers.</td></tr><tr><td>Garage / hangar</td><td>The marker players park at to store their aircraft.</td></tr></tbody></table><p>Every capture uses your current position. For NPCs and spawns, face the way the NPC or the aircraft nose should point.</p><p>If a custom airport sits within 500 m of a built-in one without <strong>Replaces</strong> set, the Airports tab shows an overlap warning.</p><h3 id="capture-walk" tabindex="-1">Capture Walk <a class="header-anchor" href="#capture-walk" aria-label="Permalink to &quot;Capture Walk&quot;">​</a></h3><p>Capture Walk records many points in one trip, so the panel only closes once.</p><ol><li>On the airport card, tick the box next to each row you want to capture. <strong>Select Missing</strong> ticks every row not yet set.</li><li>Click <strong>Start Capture Walk</strong>. The panel closes.</li><li>Walk to each spot and press <strong>E</strong>. The screen shows which point is next.</li><li>When the last point is captured, the panel reopens on the Airports tab.</li></ol><h2 id="adjust-a-built-in-airport" tabindex="-1">Adjust a built-in airport <a class="header-anchor" href="#adjust-a-built-in-airport" aria-label="Permalink to &quot;Adjust a built-in airport&quot;">​</a></h2><p>Built-in airports (except the Vespucci Helipad) also appear in the <strong>Airports</strong> tab, marked &quot;Built-in airport — services only&quot;. Use them when a custom map has moved things.</p><table tabindex="0"><thead><tr><th>You can capture</th><th>Notes</th></tr></thead><tbody><tr><td>Services and garage / hangar</td><td>Not on LSIA. LSIA&#39;s peds are set in <code>config.lua</code> (<code>Config.ShopPed</code>, <code>Config.TrainingPed</code>, <code>Config.MechanicPed</code>, <code>Config.CustomizePed</code>).</td></tr><tr><td>Passenger / tourist spawn</td><td>Replaces the airport&#39;s configured spot.</td></tr><tr><td>Job NPC and cargo overrides</td><td>Moves the dispatcher, the forklift and the pallets. Capture only what your map moved. Pallet 1 also moves the cargo loading point.</td></tr><tr><td>Helipads</td><td>Added to the airport&#39;s pads.</td></tr><tr><td>Plane spawn points</td><td>Used first. The airport&#39;s built-in parking becomes overflow.</td></tr></tbody></table><p>These apply after a restart.</p><h2 id="enable-or-disable-airports-locations-tab" tabindex="-1">Enable or disable airports (Locations tab) <a class="header-anchor" href="#enable-or-disable-airports-locations-tab" aria-label="Permalink to &quot;Enable or disable airports (Locations tab)&quot;">​</a></h2><p>The <strong>Locations</strong> tab lists every job location. Click <strong>Disable</strong> to close one, <strong>Enable</strong> to reopen it. The setting is saved in the database.</p><p>An airport counts as closed when a disabled location sits inside its radius. A closed airport:</p><ul><li>loses its job NPC and blip, and jobs skip it</li><li>disappears from the ATC tower console</li><li>is refused as a departure or arrival in flight plans</li><li>gets no AI traffic, including sub-company flights</li><li>is skipped by the HUD&#39;s &quot;nearest airport&quot;</li></ul><p>Built-in locations also have <strong>Delete</strong>, which hides them. A deleted location can be brought back with <strong>Restore</strong>. Custom airports are deleted in the <strong>Airports</strong> tab instead.</p><h2 id="extra-npc-locations-in-config-lua" tabindex="-1">Extra NPC locations in config.lua <a class="header-anchor" href="#extra-npc-locations-in-config-lua" aria-label="Permalink to &quot;Extra NPC locations in config.lua&quot;">​</a></h2><p>You can also place NPCs at other airports in <code>Config.Locations</code>. Each entry is optional field by field:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it places</th></tr></thead><tbody><tr><td><code>airport</code></td><td>The airport label, for display and matching</td></tr><tr><td><code>garageSpawn</code></td><td>Where bought aircraft spawn</td></tr><tr><td><code>hangarCoords</code></td><td>The hangar storage marker</td></tr><tr><td><code>dealer</code>, <code>trainer</code>, <code>cargo</code></td><td>Dealer, flight instructor and cargo dispatcher NPCs</td></tr><tr><td><code>painter</code></td><td>Painter NPC, with <code>radius</code> and <code>fee</code></td></tr><tr><td><code>mechanic</code></td><td>Mechanic NPC, with <code>tugSpawnCoords</code> for the tow tug</td></tr><tr><td><code>fuelZone</code></td><td>Refuel and service area, with <code>radius</code></td></tr></tbody></table><p><code>config.lua</code> has a commented Sandy Shores example and a blank template. The <strong>Airports</strong> tab does the same job without editing files.</p><h2 id="altitude-and-no-fly-zones" tabindex="-1">Altitude and no-fly zones <a class="header-anchor" href="#altitude-and-no-fly-zones" aria-label="Permalink to &quot;Altitude and no-fly zones&quot;">​</a></h2><p>Altitude zones set a minimum height above the ground over towns, bases and hills. 21 zones ship, from LS Downtown (380 m) to Senora Desert (30 m). They live in <code>Config.AltitudeZones</code>.</p><h3 id="what-happens-to-a-pilot" tabindex="-1">What happens to a pilot <a class="header-anchor" href="#what-happens-to-a-pilot" aria-label="Permalink to &quot;What happens to a pilot&quot;">​</a></h3><ol><li>A pilot flies below the zone&#39;s minimum. A warning appears every 4 seconds: &quot;RESTRICTED AIRSPACE&quot;, the zone name, the height to climb to and the current height.</li><li>The aircraft is pushed upwards until it is above the minimum.</li><li>If the zone has <strong>Strike on Violation</strong> on, a strike is added once the warning has run for the zone&#39;s <strong>Warn Delay</strong>. A countdown shows on screen.</li><li>Climbing above the minimum or leaving the zone ends the warning.</li></ol><p>A pilot who bails out of an aircraft more than 15 m above the ground inside a zone also gets a strike.</p><h3 id="who-is-exempt" tabindex="-1">Who is exempt <a class="header-anchor" href="#who-is-exempt" aria-label="Permalink to &quot;Who is exempt&quot;">​</a></h3><ul><li>Players with a job in <code>Config.EmergencyJobs</code> (default <code>police</code>, <code>ambulance</code>, <code>fire</code>)</li><li>Aircraft inside any airport radius</li><li>Helicopters over a helipad</li><li>An aircraft in a malfunction emergency</li><li>The medevac and firefighting job helicopters, and the crop duster over its field</li></ul><h3 id="the-zones-tab" tabindex="-1">The ZONES tab <a class="header-anchor" href="#the-zones-tab" aria-label="Permalink to &quot;The ZONES tab&quot;">​</a></h3><p>In <code>/adminps</code> &gt; <strong>Zones</strong> you can:</p><ul><li>create a zone: name, circle or polygon, planes, helicopters or both, minimum altitude (m above ground), warn delay, <strong>Allow Landing</strong>, <strong>Strike on Violation</strong></li><li>use the <strong>3D Editor</strong> to place the centre and radius, or the polygon corners, from a free camera</li><li>edit, disable or delete any zone, including the built-in ones</li><li>disable or enable all zones at once</li></ul><p>Zone edits and the on/off state are saved in the database. Zone rings show on the map for players in an aircraft (<code>Config.BlipVisibility.altitudeZones</code>).</p><h2 id="restricted-zones-and-escort-jets" tabindex="-1">Restricted zones and escort jets <a class="header-anchor" href="#restricted-zones-and-escort-jets" aria-label="Permalink to &quot;Restricted zones and escort jets&quot;">​</a></h2><p>Two zones send fighter jets after anyone who flies in: Fort Zancudo (2 jets) and Bolingbroke Penitentiary (1 jet). They are set in <code>Config.RestrictedZones</code>.</p><ol><li>The pilot enters the zone more than 50 m above the ground. A warning appears and the jets spawn to escort them.</li><li>A 30-second countdown runs.</li><li>Leaving the zone before the countdown ends sends the jets away.</li><li>If the pilot is still inside after 30 seconds, the jets open fire.</li><li>Once they have opened fire, the jets keep chasing until the pilot lands or is 1,500 m from the zone centre.</li></ol><p>Only the pilot triggers it, not passengers. Helicopters over a helipad, aircraft in a malfunction emergency, and the medevac and firefighting job helicopters are exempt. Emergency jobs are <strong>not</strong> exempt here. Switch the whole system off with <code>Config.Features.restrictedZones = false</code>.</p><h2 id="runway-discipline" tabindex="-1">Runway discipline <a class="header-anchor" href="#runway-discipline" aria-label="Permalink to &quot;Runway discipline&quot;">​</a></h2><p>Planes at an airport must take off and land on a runway. The runway area is the full runway length plus 15 m at each end, and 15 m either side of the centreline.</p><ul><li>Only the moment of takeoff and landing is checked. Taxiing anywhere is fine.</li><li>It only applies inside an airport radius. Bush strips and fields are never judged.</li><li>Helicopters and water takeoffs and landings are exempt.</li><li>A forced landing during a malfunction, or in a heavily damaged aircraft, is not penalised (<code>exemptDamaged = true</code>).</li></ul><table tabindex="0"><thead><tr><th>Situation</th><th>Penalty</th></tr></thead><tbody><tr><td>On a mission</td><td>Every payout of that mission is cut by 50% (<code>missionPayCutPct</code>). The cut does not stack.</td></tr><tr><td>Free flight</td><td>A warning. Every 10th warning (<code>freeFlightWarnings</code>) becomes a strike.</td></tr></tbody></table><p>Settings are in <code>Config.RunwayDiscipline</code>. Any player can type <code>/rwyzones</code> to show or hide the runway areas in the world.</p><h2 id="taxi-network-airportnav" tabindex="-1">Taxi network (/airportnav) <a class="header-anchor" href="#taxi-network-airportnav" aria-label="Permalink to &quot;Taxi network (/airportnav)&quot;">​</a></h2><p>The taxi network is a map of taxiways and parking stands at an airport. AI aircraft follow it to taxi between the runway and the stands. The tower console draws it too.</p><ul><li>LSIA ships with its layout already drawn.</li><li>Admins draw other airports in game. Saving is admin-only and needs <code>Config.AirportNavigation.editorEnabled = true</code> (it is on in the shipped <code>config.lua</code>).</li><li>A saved layout is stored in the database. It replaces the shipped layout for that airport, and survives restarts and script updates.</li><li>Every save is kept as a version, so you can go back.</li></ul><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/airportnav</code></td><td>Show or hide the layout within 300 m of you</td></tr><tr><td><code>/airportnav edit</code></td><td>Open or close the editor at the airport you stand in</td></tr><tr><td><code>/airportnav save</code></td><td>Save the layout. It goes live for everyone.</td></tr><tr><td><code>/airportnav versions</code></td><td>List saved versions in the F8 console</td></tr><tr><td><code>/airportnav restore &lt;n&gt;</code></td><td>Bring back a saved version</td></tr><tr><td><code>/airportnav reset confirm</code></td><td>Drop the saved layout and go back to the shipped one</td></tr></tbody></table><p>The editor opens a top-down camera. Use <strong>WASD</strong> to pan and the mouse wheel to zoom. The on-screen help lists the drawing controls.</p><h2 id="blip-visibility" tabindex="-1">Blip visibility <a class="header-anchor" href="#blip-visibility" aria-label="Permalink to &quot;Blip visibility&quot;">​</a></h2><p><code>Config.BlipVisibility</code> decides who sees each map blip.</p><table tabindex="0"><thead><tr><th>Value</th><th>Who sees it</th></tr></thead><tbody><tr><td><code>&#39;always&#39;</code></td><td>Every player</td></tr><tr><td><code>&#39;pilot&#39;</code></td><td>Players with the pilot job. Hidden when the pilot job is not required (open access).</td></tr><tr><td><code>&#39;inPlane&#39;</code></td><td>Players sitting in a plane or helicopter</td></tr><tr><td><code>&#39;pilotOrPlane&#39;</code></td><td>Pilots, or anyone in an aircraft. Same as <code>&#39;inPlane&#39;</code> in open access.</td></tr><tr><td><code>&#39;hidden&#39;</code></td><td>Nobody</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Blip</th><th>Default</th></tr></thead><tbody><tr><td><code>dealer</code></td><td><code>&#39;always&#39;</code></td></tr><tr><td><code>instructor</code></td><td><code>&#39;always&#39;</code></td></tr><tr><td><code>cargo</code></td><td><code>&#39;always&#39;</code></td></tr><tr><td><code>groundServices</code></td><td><code>&#39;always&#39;</code></td></tr><tr><td><code>painter</code></td><td><code>&#39;pilotOrPlane&#39;</code></td></tr><tr><td><code>mechanic</code></td><td><code>&#39;pilotOrPlane&#39;</code></td></tr><tr><td><code>hangar</code></td><td><code>&#39;pilotOrPlane&#39;</code></td></tr><tr><td><code>runway</code></td><td><code>&#39;pilotOrPlane&#39;</code></td></tr><tr><td><code>taxiway</code></td><td><code>&#39;pilotOrPlane&#39;</code></td></tr><tr><td><code>altitudeZones</code></td><td><code>&#39;inPlane&#39;</code></td></tr></tbody></table>',58)])])}const g=e(i,[["render",d]]);export{u as __pageData,g as default};
